"""Four-arm report from accepted prior A/C/B and newly scored D only."""
import importlib.util,json,math,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4];OUT=ROOT/'results/midtraining/sft905-benchmark-gpu-01';OLD=ROOT/'midtraining/evaluation/ablation_gpu';MODEL=ROOT/'checkpoints/exports/nemochat_sft905_hf_bf16_01'
s=importlib.util.spec_from_file_location('prior_validation',OLD/'controller.py');c=importlib.util.module_from_spec(s);s.loader.exec_module(c)
ORDER=['A','C','B','D'];LABELS={'A':'A: BASE19074','C':'C: LM+KD1000','B':'B: ordinary LM1000','D':'D: SFT905 after C'}
def main():
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 from PIL import Image
 suite=c.load_suite();reports={a:c.read(c.OUT/(a+'-full01/report.json')) for a in ORDER[:-1]};reports['D']=c.read(OUT/'D-full01/report.json')
 proofs={a:c.validate_report(reports[a],suite,MODEL if a=='D' else c.MODELS[a]) for a in ORDER}
 full=c.read(OUT/'engine.create.json');engine=c.engine().request('GET',f"/containers/{full['id']}/json");c.clean_engine(engine,full['id'])
 groups=[('MMLU diagnostic\n200 questions, 5-shot',lambda q:q['task'].startswith('mmlu_'),'acc'),('ARC-Challenge\n100 questions, 0-shot',lambda q:q['task']=='arc_challenge','acc_norm'),('HellaSwag\n100 questions, 0-shot',lambda q:q['task']=='hellaswag','acc_norm')]
 scores={a:[sum(q[m] for q in r['questions'] if pred(q))/sum(pred(q) for q in r['questions']) for _,pred,m in groups] for a,r in reports.items()}
 sources=sorted({h['source'] for h in suite['heldout']});held={a:{'Overall':r['heldout_full_vocab_nll'],**{src:sum(w['nll_sum'] for w in r['heldout'] if w['source']==src)/sum(w['target_count'] for w in r['heldout'] if w['source']==src) for src in sources}} for a,r in reports.items()}
 colors=['#4477aa','#ee7733','#228833','#aa3377']
 fig,ax=plt.subplots(figsize=(13,7))
 for i,a in enumerate(ORDER):
  bars=ax.bar([j+(i-1.5)*.20 for j in range(3)],[100*v for v in scores[a]],width=.19,color=colors[i],label=LABELS[a]);ax.bar_label(bars,fmt='%.1f%%',padding=4,fontsize=10)
 ax.set_xticks(range(3),[g[0] for g in groups]);ax.set_ylim(0,80);ax.set_ylabel('Accuracy (%) — MMLU acc; ARC / HellaSwag acc_norm');ax.set_title('NemoChat four-arm same-raw-prompt GPU comparison\nD = actual final SFT905; A/C/B restored from accepted reports');ax.legend(ncol=2,loc='upper left');ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True)
 fig.text(.05,.025,'400 frozen questions / 1,600 choices | Diagnostic subsets, not full benchmark/leaderboard\nD has additional 85,001,437 assistant-target exposures; NOT a controlled KD ablation.\nSame RAW prompts, no chat template; SFT migrated tokenizer has identical frozen prompt/choice token IDs.',fontsize=9)
 fig.subplots_adjust(bottom=.24,top=.87);benchmark=OUT/'benchmark-four-arms-SFT905.png';fig.savefig(benchmark,dpi=150);plt.close(fig)
 fig,axes=plt.subplots(2,1,figsize=(15,10));names=['Overall',*sources]
 for i,a in enumerate(ORDER):
  vals=[held[a][n] for n in names]
  for ax,ys in zip(axes,[vals,[math.exp(v) for v in vals]]):
   bars=ax.bar([j+(i-1.5)*.2 for j in range(len(names))],ys,width=.19,label=LABELS[a],color=colors[i]);ax.bar_label(bars,fmt='%.3f',padding=4,fontsize=8)
 for ax,label in zip(axes,['Full-vocabulary token NLL (lower is better)','PPL = exp(NLL) (lower is better)']):
  ax.set_xticks(range(len(names)),['Overall\n65,536 targets',*[n.replace('_',' ')+'\n16,384 targets' for n in sources]],fontsize=9);ax.set_ylabel(label);ax.grid(axis='y',alpha=.2);ax.set_axisbelow(True);ax.margins(y=.23)
 axes[0].legend(ncol=2,fontsize=10);fig.suptitle('NemoChat four-arm pretraining-heldout retention diagnostic\nSame 64 frozen windows x 1,024 targets; NOT SFT validation Loss',fontsize=14)
 fig.text(.05,.015,'A: BASE19074 | C: LM+KD1000 | B: ordinary LM1000 | D: SFT905 after C\nD has additional assistant supervision. Source byte integrity waived; native/HF kernel parity not tested.',fontsize=10)
 fig.tight_layout(rect=(0,.06,1,.94));hold=OUT/'heldout-four-arms-SFT905.png';fig.savefig(hold,dpi=150);plt.close(fig)
 for path in [benchmark,hold]:
  with Image.open(path) as image:image.verify()
 summary={'status':'verified_four_arm_same_prompt_comparison','order':ORDER,'labels':LABELS,'suite_sha256':suite['suite_sha256'],'reports':{a:str(OUT/'D-full01/report.json' if a=='D' else c.OUT/(a+'-full01/report.json')) for a in ORDER},'coverage':proofs,'benchmark_accuracy':scores,'benchmark_metrics_order':['mmlu_acc','arc_acc_norm','hellaswag_acc_norm'],'heldout_nll':held,'heldout_ppl':{a:{src:math.exp(nll) for src,nll in vals.items()} for a,vals in held.items()},'D_minus_C_accuracy_percentage_points':[100*(x-y) for x,y in zip(scores['D'],scores['C'])],'D_minus_C_heldout_nll':held['D']['Overall']-held['C']['Overall'],'engine_id':full['id'],'D_engine_state':engine['State'],'images':[str(benchmark),str(hold)],'D_additional_assistant_target_exposures':85001437,'comparison':'same frozen RAW prompts, NOT chat-template benchmark; D additional SFT, not controlled KD ablation','source_integrity':'not_checked_explicit_user_waiver','native_HF_logit_parity':'not_run','A_C_B_rerun':False}
 (OUT/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
 table='| Arm | MMLU acc /200 | ARC acc_norm /100 | HellaSwag acc_norm /100 | Pretraining-heldout NLL /65,536 targets | PPL |\n|---|---:|---:|---:|---:|---:|\n'
 for a in ORDER:table+='| '+LABELS[a]+' | '+' | '.join(f'{100*v:.2f}%' for v in scores[a])+f" | {held[a]['Overall']:.6f} | {math.exp(held[a]['Overall']):.6f} |\n"
 en='# SFT905 benchmark: four-arm same-prompt comparison\n\n'+table+'\nOnly D was newly executed; A/C/B are unchanged accepted GPU reports. D is the final native SFT905 export, initialized from C, with an additional 85,001,437 supervised assistant-target exposures. This is not a controlled KD ablation.\n\nProtocol: exact frozen diagnostic subsets, MMLU 10 subjects ×20 test questions at 5-shot, ARC-Challenge100 test and HellaSwag100 validation at 0-shot. Not full benchmarks or leaderboard scores; contamination is not established. All 400 question IDs, 1,600 choices, 64 heldout windows and 65,536 pretraining-heldout targets are verified. Pretraining-heldout NLL/PPL is not SFT validation Loss.\n\nThe same raw frozen prompt strings are scored without a chat template. D retains its exact migrated SFT tokenizer; only aliases18..29 differ. All 1,600 frozen prompt/choice encodings match exactly and no heldout window uses those aliases. The old scorer is unchanged; a task-local wrapper adapts only the full-vocab identity guard after those checks. Chat-conditioned examples are reported separately.\n\nRuntime: official Transformers5.12.1 / Torch2.13.0a0+8145d630e8.nv26.06 on B300 GPU0, eager BF16, TF32=false, no padding, full-vocabulary likelihood; not the unmodified official harness backend. Native/HF logit parity unrun; checkpoint payload byte audits explicitly waived.\n\nD Engine `'+full['id']+'`: clean exit0, OOMKilled=false, all 400 per-question receipts re-read and checked. Scorer elapsed '+f"{reports['D']['elapsed_seconds']:.3f}"+' seconds. No training, downloads, Hub writes, baseline reruns, subset shrink or retries.\n\nObserved D vs C changes: '+', '.join(f'{v:+.2f} pp' for v in summary['D_minus_C_accuracy_percentage_points'])+' (MMLU/ARC/HellaSwag); pretraining-heldout NLL '+f"{summary['D_minus_C_heldout_nll']:+.6f}"+'. These are finite-sample diagnostic observations, not a general quality or causal claim.\n\n![Benchmark](benchmark-four-arms-SFT905.png)\n\n![Heldout](heldout-four-arms-SFT905.png)\n'
 ko='# SFT905 benchmark: 동일 프롬프트 4-arm 비교\n\n'+table+'\nD만 새로 실행했으며 A/C/B는 기존 accepted GPU report를 그대로 읽었습니다. D는 C에서 시작한 최종 native SFT905로, 85,001,437개의 assistant-target 노출이 추가되었으므로 통제된 KD ablation이 아닙니다.\n\nMMLU는 10개 subject×20개 test 문항의 5-shot diagnostic subset이고 ARC-Challenge와 HellaSwag는 각각 100문항 0-shot입니다. 전체 benchmark나 leaderboard 결과가 아니고 contamination 여부는 확인되지 않았습니다. 400개 question ID, 1,600개 choice, 64개 heldout window, 65,536개 pretraining target을 모두 검증했습니다. Heldout NLL/PPL은 SFT validation Loss가 아닙니다.\n\n기존과 동일한 RAW prompt를 사용하고 chat template은 적용하지 않았습니다. D의 migrated SFT tokenizer를 유지했고, 변경 alias는18..29뿐이며 전체 1,600개 prompt/choice의 token ID가 기존 frozen encoding과 정확히 일치했습니다. 기존 scorer는 변경하지 않았고 full-vocab identity guard만 별도 wrapper에서 검증 후 조정했습니다. 공식 chat-template 예시는 별도 파일입니다.\n\nOfficial Transformers5.12.1, Torch2.13, B300 GPU0, eager BF16, TF32=false, no-padding, full-vocabulary likelihood입니다. Unmodified official harness 실행은 아니며 native/HF logit parity는 실행하지 않았고 checkpoint byte audit은 사용자 요청으로 생략했습니다. D Engine은 clean exit0/OOMKilled=false이며 모든 per-question receipt를 재확인했습니다. 학습/다운로드/Hub write/기존 arm 재실행/축소/재시도는 없었습니다.\n\nD vs C 변화(MMLU/ARC/HellaSwag): '+', '.join(f'{v:+.2f} pp' for v in summary['D_minus_C_accuracy_percentage_points'])+'; pretraining-heldout NLL '+f"{summary['D_minus_C_heldout_nll']:+.6f}"+'. 제한된 표본의 관측값이지 일반 품질이나 인과 효과를 뜻하지 않습니다.\n\n![Benchmark](benchmark-four-arms-SFT905.png)\n\n![Heldout](heldout-four-arms-SFT905.png)\n'
 (OUT/'FINAL_REPORT.md').write_text(en);(OUT/'FINAL_REPORT.ko.md').write_text(ko);print(table);print(json.dumps({'images':summary['images'],'D_minus_C_pp':summary['D_minus_C_accuracy_percentage_points'],'D_minus_C_nll':summary['D_minus_C_heldout_nll']},indent=2))
if __name__=='__main__':main()
